'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let vehicles=[{id:'VB-101',level:'ALS',crew:'A. Morgan · J. Ade',status:'Available',fuel:82,lat:32.78,lon:-96.80},{id:'VB-102',level:'BLS',crew:'S. Okafor · M. Lee',status:'Available',fuel:64,lat:32.79,lon:-96.81},{id:'VB-103',level:'ALS',crew:'T. Bello · K. James',status:'Maintenance',fuel:38,lat:32.76,lon:-96.82}];
let trips=[{id:'VB-2401',name:'Demo patient A',type:'Scheduled NEMT',care:'BLS',pickup:'Northside residence',destination:'Olamide Medical',status:'Requested',notes:'Wheelchair assistance requested',lat:32.785,lon:-96.8},{id:'VB-2402',name:'Demo patient B',type:'Emergency simulation',care:'ALS',pickup:'Central community center',destination:'Olamide Medical',status:'Requested',notes:'Training scenario only',lat:32.78,lon:-96.805}];
let hospitals=[{name:'Olamide Medical',status:'Accepting',capacity:12,updated:new Date().toISOString()},{name:'Central Medical Center',status:'Diversion',capacity:0,updated:new Date().toISOString()}], records=[],audit=[],page='Overview',profile={},settings={market:'Not configured',model:'Private fleet',emergency:'Disabled',sms:'Not configured',video:''};
const pages={'Dispatcher':['Overview','Requests','Fleet','Hospitals'],'Patient':['Book transport','My journeys','Medical profile','Emergency contacts'],'Driver & Paramedic':['Crew workspace','Care records','Hospitals','Consultation'],'Hospital':['Hospitals','Incoming arrivals'],'Admin':['Overview','Fleet','Hospitals','Settings','Audit log']};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function log(t){audit.unshift({time:new Date().toLocaleTimeString(),event:t})}function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function go(p){page=p;render()}$('#role').onchange=()=>{page=pages[$('#role').value][0];render()};
function map(){return `<div class="map" aria-label="Illustrative service area map, not live vehicle tracking"><svg viewBox="0 0 700 330" preserveAspectRatio="none"><rect width="700" height="330" fill="#ecf0e6"/><path d="M0 80L700 140M0 250L700 190M100 0L180 330M460 0L390 330M630 0L530 330" stroke="#fff" stroke-width="20"/><path d="M0 80L700 140M0 250L700 190M100 0L180 330M460 0L390 330M630 0L530 330" stroke="#dce2d8" stroke-width="2"/><path d="M0 310Q220 240 300 120T600 0" fill="none" stroke="#c9ddd6" stroke-width="30"/><path d="M280 130L425 130L425 185L535 185" fill="none" stroke="#348677" stroke-width="4" stroke-dasharray="7 5"/><text x="200" y="50" fill="#8d9c8b" font-size="11">NORTHSIDE</text><text x="250" y="280" fill="#8d9c8b" font-size="11">CENTRAL DISTRICT</text></svg><span class="unit one">✚ VB-101</span><span class="unit two">✚ VB-102</span><span class="unit three">✚ VB-103</span><span class="hospital">H</span><span class="map-label">Illustrative map · Dallas demo coordinates · No live ETA</span></div>`}
function stats(){return `<div class="stats"><div class="stat"><label>ACTIVE JOURNEYS</label><strong>${trips.filter(t=>!['Completed','Cancelled'].includes(t.status)).length.toString().padStart(2,'0')}</strong><small>Across your service area</small></div><div class="stat"><label>AVAILABLE VEHICLES</label><strong>${vehicles.filter(v=>v.status==='Available').length.toString().padStart(2,'0')}</strong><small>Ready for assignment</small></div><div class="stat"><label>COMPLETED JOURNEYS</label><strong>${trips.filter(t=>t.status==='Completed').length.toString().padStart(2,'0')}</strong><small>This demo session</small></div><div class="stat"><label>RECEIVING HOSPITALS</label><strong>${hospitals.filter(h=>h.status==='Accepting').length.toString().padStart(2,'0')}</strong><small>Manually reported status</small></div></div>`}
function queue(){return trips.filter(t=>t.status==='Requested').map(t=>`<div class="queue"><div class="row"><h3>${esc(t.id)}</h3><span class="pill">${esc(t.care)}</span></div><p style="margin:6px 0;font-size:12px">${esc(t.pickup)} → ${esc(t.destination)}</p><small>${esc(t.type)} · Awaiting assignment</small><br><button class="btn secondary" onclick="dispatch('${t.id}')">Review & assign ↗</button></div>`).join('')||'<p class="empty">All requests are assigned.</p>'}
function table(){return `<div class="table-wrap"><table><thead><tr><th>JOURNEY</th><th>PATIENT / PICKUP</th><th>CARE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${trips.map(t=>`<tr><td><b>${esc(t.id)}</b><br><small>${esc(t.type)}</small></td><td>${esc(t.name)}<br><small>${esc(t.pickup)}</small></td><td>${esc(t.care)}</td><td><span class="pill">${esc(t.status)}</span></td><td><button class="btn secondary" onclick="detail('${t.id}')">Open</button></td></tr>`).join('')}</tbody></table></div>`}
function render(){const role=$('#role').value;$('#nav').innerHTML=pages[role].map((p,i)=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><b>${(['◈','▤','⊞','⊕','⚙','≡'][i]||'◈')}</b>${p}</button>`).join('');$('#title').textContent=page==='Overview'?'Every journey. Connected.':page;let out='';
if(page==='Overview')out=`<section class="hero"><img src="/assets/brand-art.jpg" alt="VitaBridge ambulance and care team" onerror="this.style.display='none'"><div class="hero-text"><span class="pill">YOUR BRIDGE TO BETTER CARE</span><h2>The right care.<br>The right place. On time.</h2><p>A shared view of your fleet, your teams,<br>and every patient journey.</p><button class="btn" onclick="booking()">＋ New transport request</button></div></section>${stats()}<div class="grid"><section class="card"><div class="row"><div><h2>Service area</h2><span class="sub">A coordinated view of your operations</span></div><span class="badge">DEMO MAP</span></div>${map()}<div class="row sub"><span>● Available &nbsp; <span style="color:#c27850">●</span> In service</span><button class="btn secondary" onclick="go('Fleet')">View fleet ↗</button></div></section><section class="card"><div class="row"><h2>Dispatch queue</h2><span class="badge">${trips.filter(t=>t.status==='Requested').length} pending</span></div>${queue()}</section></div><section class="card" style="margin-top:20px"><div class="row"><h2>Recent journeys</h2><button class="btn secondary" onclick="go('Requests')">View all ↗</button></div>${table()}</section>`;
else if(['Requests','My journeys','Incoming arrivals'].includes(page))out=`<div class="card"><div class="row"><h2>Transport journeys</h2><button class="btn" onclick="booking()">＋ Book transport</button></div>${table()}</div>`;
else if(page==='Book transport')out=`<div class="grid"><div class="card"><span class="pill">PATIENT TRANSPORT</span><h2 style="margin-top:15px">Care starts with a connection.</h2><p>Plan an appointment trip or explore an emergency request simulation.</p><button class="btn big-action red" onclick="emergency()">✚ Emergency request simulation</button><p class="sub">This demonstration cannot contact emergency services.</p><button class="btn big-action" onclick="booking()">Schedule medical transport →</button></div><div class="card"><h2>Your journey at a glance</h2>${map()}<p class="sub">Live GPS and traffic ETA require a mapping and fleet telemetry integration.</p></div></div>`;
else if(page==='Fleet')out=`<div class="card"><div class="row"><h2>Fleet & readiness</h2><button class="btn" onclick="editVehicle()">＋ Add vehicle</button></div><div class="tiles" style="margin-top:22px">${vehicles.map(v=>`<div class="tile"><span class="pill">${esc(v.level)}</span><h2 style="margin-top:15px">${esc(v.id)}</h2><p>${esc(v.crew)}</p><span class="badge">${esc(v.status)}</span><p>Fuel ${v.fuel}%</p><div class="progress"><span style="width:${v.fuel}%"></span></div><p>Maintenance checks required before service.</p><button class="btn secondary" onclick="editVehicle('${esc(v.id)}')">Manage vehicle</button></div>`).join('')}</div></div>`;
else if(page==='Hospitals')out=`<div class="card"><h2>Receiving facilities</h2><p class="sub">Status is entered by the hospital or dispatcher. Confirm directly before choosing a destination.</p>${hospitals.map((h,i)=>`<div class="queue"><div class="row"><div><h3>${esc(h.name)}</h3><p class="sub">${h.capacity} reported beds · Updated ${new Date(h.updated).toLocaleTimeString()}</p></div><span class="pill">${esc(h.status)}</span></div>${['Hospital','Dispatcher','Admin'].includes(role)?`<button class="btn secondary" onclick="hospital(${i})">Update status</button>`:''}</div>`).join('')}</div>`;
else if(page==='Crew workspace')out=`<div class="card"><h2>Assigned journeys</h2><p class="sub">Crew demonstration · Assigned patient context is visible here.</p>${trips.filter(t=>t.vehicle&&!['Completed','Cancelled'].includes(t.status)).map(t=>`<div class="queue"><div class="row"><div><h3>${esc(t.id)} · ${esc(t.vehicle)}</h3><p>${esc(t.pickup)} → ${esc(t.destination)}</p><p class="sub">${esc(t.notes)}</p></div><span class="pill">${esc(t.status)}</span></div><div class="actions"><button class="btn" onclick="advance('${t.id}')">Advance trip</button><button class="btn secondary" onclick="care('${t.id}')">Record patient care</button><button class="btn secondary" onclick="navigate('${t.id}')">Open navigation ↗</button></div></div>`).join('')||'<p class="empty">No assigned journeys. Assign a request in the Dispatcher workspace.</p>'}</div>`;
else if(page==='Care records')out=`<div class="card"><h2>Patient care records</h2><p class="sub">Synthetic training records only. No patient data is retained after reload.</p>${records.map(r=>`<div class="queue"><h3>${esc(r.trip)} · ${esc(r.time)}</h3><p>Vitals: ${esc(r.vitals)}</p><p>Medication: ${esc(r.medication)}</p><p>Treatment / handoff: ${esc(r.notes)}</p></div>`).join('')||'<p class="empty">Use Record patient care on an assigned trip.</p>'}</div>`;
else if(page==='Medical profile')out=`<div class="card"><h2>Medical profile · demonstration</h2><p class="sub">Use fictitious information. This preview does not securely store or share medical profiles.</p><form onsubmit="saveProfile(event)"><div class="two"><label>Blood type<input name="blood" value="${esc(profile.blood||'')}"></label><label>Age<input name="age" type="number" min="0" max="125" value="${esc(profile.age||'')}"></label></div><label>Allergies<textarea name="allergies">${esc(profile.allergies||'')}</textarea></label><label>Conditions<textarea name="conditions">${esc(profile.conditions||'')}</textarea></label><label>Insurance plan (demo only)<input name="insurance" value="${esc(profile.insurance||'')}"></label><button class="btn">Keep in this demo session</button></form></div>`;
else if(page==='Emergency contacts')out=`<div class="card"><h2>Emergency contacts</h2><p>Contact alerts require a configured SMS provider and consent. No messages are sent from this preview.</p><form onsubmit="event.preventDefault();toast('Demo contact added for this session; no SMS sent.');this.reset()"><label>Contact name<input required></label><label>Telephone<input type="tel" required></label><label><span><input type="checkbox" required> I have permission to notify this contact.</span></label><button class="btn">Add demo contact</button></form></div>`;
else if(page==='Consultation')out=`<div class="card"><h2>Medical director consultation</h2><p>Connect an approved telemedicine provider in Admin settings. This preview does not transmit patient audio, video, or records.</p><button class="btn" onclick="consult()">Open configured consultation service ↗</button></div>`;
else if(page==='Settings')out=`<div class="card"><h2>Service configuration</h2><p class="sub">Demo controls only. Deployment configuration is separate.</p><form onsubmit="saveSettings(event)"><label>Target market<input name="market" value="${esc(settings.market)}"></label><label>Operating model<select name="model"><option>Private fleet</option><option>Aggregator marketplace</option><option>Hybrid</option></select></label><label>Approved telemedicine URL<input name="video" type="url" value="${esc(settings.video)}" placeholder="https://your-approved-provider.example"></label><button class="btn">Save demo settings</button></form><hr><h3>Integration readiness</h3><p>Emergency dispatch: disabled<br>SMS: not configured<br>Traffic routing & vehicle telemetry: not configured<br>Authentication and PHI environment: requires operator deployment<br>Redundancy / 99.99% SLA: not provisioned or verified</p><button class="btn secondary" onclick="privacy()">View launch requirements</button></div>`;
else if(page==='Audit log')out=`<div class="card"><h2>Session activity</h2>${audit.map(a=>`<p><span class="sub">${esc(a.time)}</span> · ${esc(a.event)}</p>`).join('')||'<p class="empty">No activity yet.</p>'}</div>`;
$('#content').innerHTML=out;}
function booking(){modal(`<h2>New transport request</h2><p class="sub">Demo booking · no real ambulance will be sent.</p><form onsubmit="submitBooking(event)"><label>Patient display name<input name="name" required maxlength="80" placeholder="Fictitious name only"></label><label>Pickup address<input name="pickup" required maxlength="200"></label><label>Destination<input name="destination" required value="Olamide Medical"></label><div class="two"><label>Care level<select name="care"><option>BLS</option><option>ALS</option></select></label><label>Trip type<select name="type"><option>Scheduled NEMT</option><option>Emergency simulation</option></select></label></div><label>Scheduled time<input name="scheduled" type="datetime-local"></label><label>Training notes<textarea name="notes" maxlength="1000"></textarea></label><button type="button" class="btn secondary" onclick="locate(this)">Use my location (optional)</button><input name="lat" type="hidden"><input name="lon" type="hidden"><button class="btn">Create demo request</button></form>`)}
function locate(b){if(!navigator.geolocation)return toast('Location unavailable. Enter a pickup address.');navigator.geolocation.getCurrentPosition(p=>{b.form.lat.value=p.coords.latitude;b.form.lon.value=p.coords.longitude;b.textContent='Location attached';},()=>toast('Location was not shared. Enter a pickup address.'),{timeout:10000})}
function submitBooking(e){e.preventDefault();const t=Object.fromEntries(new FormData(e.target));if(t.type==='Scheduled NEMT'&&!t.scheduled)return toast('Select a scheduled pickup time.');t.id='VB-'+(2401+trips.length);t.status='Requested';trips.unshift(t);log('Created '+t.id);$('#modal').close();render();toast('Demo request created. No emergency services contacted.')}
function emergency(){modal(`<h2>Emergency simulation</h2><p>This platform is not connected to an emergency dispatch operator. Call your local emergency number for immediate help.</p><button class="btn" onclick="booking()">Continue with a demo request</button>`)}
function distance(a,b){const r=Math.PI/180,dlat=(a.lat-b.lat)*r,dlon=(a.lon-b.lon)*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2))}
function dispatch(id){const t=trips.find(t=>t.id===id);const eligible=vehicles.filter(v=>v.status==='Available'&&(t.care==='BLS'||v.level==='ALS')).sort((a,b)=>distance(a,t)-distance(b,t));modal(`<h2>Assign ${esc(id)}</h2><p>${esc(t.pickup)} → ${esc(t.destination)}</p><p class="sub">Rules-based recommendation: available vehicles with matching care capability, ordered by straight-line distance when coordinates exist. A dispatcher must confirm suitability.</p>${eligible.length?`<form onsubmit="assign(event,'${id}')"><label>Available unit<select name="vehicle">${eligible.map((v,i)=>`<option value="${v.id}">${v.id} · ${v.level}${i===0?' · Recommended':''}</option>`).join('')}</select></label><button class="btn">Confirm demo assignment</button></form>`:'<p>No suitable available vehicle. Request remains unassigned.</p>'}`)}
function assign(e,id){e.preventDefault();const t=trips.find(t=>t.id===id),v=vehicles.find(v=>v.id===e.target.vehicle.value);if(t.status!=='Requested'||v.status!=='Available')return toast('Availability changed. Review the request again.');t.vehicle=v.id;t.status='Assigned';v.status='En route';log('Assigned '+id+' to '+v.id);$('#modal').close();render();toast('Demo crew assigned. Contact alerts are not configured.')}
function advance(id){const t=trips.find(t=>t.id===id),flow=['Assigned','En route','On scene','Transporting','At hospital','Completed'];let i=flow.indexOf(t.status);if(i<0||i===5)return;t.status=flow[i+1];if(t.status==='Completed')vehicles.find(v=>v.id===t.vehicle).status='Available';log(id+' → '+t.status);render();toast(t.status)}
function detail(id){const t=trips.find(t=>t.id===id);modal(`<h2>${esc(t.id)}</h2><p>${esc(t.name)} · ${esc(t.care)}</p><p>${esc(t.pickup)} → ${esc(t.destination)}</p><p>${esc(t.notes)}</p><p>Status: ${esc(t.status)}<br>Unit: ${esc(t.vehicle||'Unassigned')}<br>Scheduled: ${esc(t.scheduled||'Not scheduled')}</p>${t.status==='Requested'&&$('#role').value==='Dispatcher'?`<button class="btn" onclick="dispatch('${id}')">Review assignment</button>`:''}`)}
function care(id){modal(`<h2>Patient care · ${id}</h2><p class="sub">Training record only · enter no real PHI.</p><form onsubmit="saveCare(event,'${id}')"><label>Vitals (include units and time)<input name="vitals" required maxlength="500"></label><label>Medication / dose / time<textarea name="medication" maxlength="1000"></textarea></label><label>Treatment & hospital handoff<textarea name="notes" required maxlength="2000"></textarea></label><button class="btn">Save training record</button></form>`)}
function saveCare(e,id){e.preventDefault();records.unshift({...Object.fromEntries(new FormData(e.target)),trip:id,time:new Date().toLocaleTimeString()});log('Care record saved for '+id);$('#modal').close();toast('Training record saved for this session.')}
function navigate(id){const t=trips.find(t=>t.id===id);window.open('https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(t.status==='Transporting'?t.destination:t.pickup),'_blank','noopener');toast('Standard navigation. Emergency vehicle routing is not supported.')}
function hospital(i){const h=hospitals[i];modal(`<h2>${esc(h.name)}</h2><form onsubmit="saveHospital(event,${i})"><label>Receiving status<select name="status"><option>Accepting</option><option>Diversion</option><option>Unknown</option></select></label><label>Reported available beds<input type="number" name="capacity" min="0" max="999" value="${h.capacity}" required></label><button class="btn">Update reported status</button></form>`)}
function saveHospital(e,i){e.preventDefault();Object.assign(hospitals[i],Object.fromEntries(new FormData(e.target)),{updated:new Date().toISOString()});log('Hospital status updated');$('#modal').close();render()}
function editVehicle(id){const v=vehicles.find(v=>v.id===id)||{};modal(`<h2>${id?'Manage':'Add'} vehicle</h2><form onsubmit="saveVehicle(event,'${id||''}')"><label>Unit ID<input name="id" pattern="[A-Za-z0-9-]+" value="${esc(v.id||'')}" ${id?'readonly':''} required></label><label>Crew<input name="crew" value="${esc(v.crew||'')}" required></label><label>Care level<select name="level"><option ${v.level==='BLS'?'selected':''}>BLS</option><option ${v.level==='ALS'?'selected':''}>ALS</option></select></label><label>Readiness<select name="status"><option ${v.status==='Available'?'selected':''}>Available</option><option ${v.status==='Maintenance'?'selected':''}>Maintenance</option><option ${v.status==='En route'?'selected':''}>En route</option></select></label><label>Fuel %<input type="number" name="fuel" min="0" max="100" value="${v.fuel??100}" required></label><button class="btn">Save vehicle</button></form>`)}
function saveVehicle(e,id){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!id&&vehicles.some(x=>x.id===v.id))return toast('Unit ID already exists.');if(id&&trips.some(t=>t.vehicle===id&&!['Completed','Cancelled'].includes(t.status))&&v.status==='Available')return toast('Complete the assigned journey before marking this unit available.');v.fuel=Number(v.fuel);if(id)Object.assign(vehicles.find(x=>x.id===id),v);else vehicles.push({...v,lat:32.78,lon:-96.8});log('Fleet updated: '+v.id);$('#modal').close();render()}
function saveProfile(e){e.preventDefault();profile=Object.fromEntries(new FormData(e.target));toast('Demo profile retained in memory only.');log('Demo profile updated')}
function saveSettings(e){e.preventDefault();Object.assign(settings,Object.fromEntries(new FormData(e.target)));toast('Demo settings updated.');log('Settings updated')}
function consult(){if(!settings.video)return toast('Add an approved consultation URL in Admin settings.');const u=new URL(settings.video);if(u.protocol!=='https:')return toast('Consultation URL must use HTTPS.');window.open(u.href,'_blank','noopener')}
function privacy(){modal(`<h2>Privacy & launch readiness</h2><p>This is an interactive demonstration using synthetic data. Role switching is for review and is not authentication. Patient profiles and care records are kept only in memory and reset on reload.</p><p>Live launch requires identity and access controls, a contracted dispatch operator, licensed crews, confirmed service coverage, mapping/telemetry, consented SMS alerts, approved telemedicine, encrypted clinical storage, audit retention, backups, incident procedures, and tested failover.</p><p>No HIPAA/GDPR certification, emergency response guarantee, or 99.99% uptime claim is made. Offline mode caches the application shell only; it does not queue emergency requests or cache PHI. Call local emergency services if you need immediate assistance.</p>`)}
window.addEventListener('offline',()=>toast('Offline: demo shell only. No emergency requests can be transmitted.'));if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');render();
